insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000301', 'dormitorio', 1, 'globe_01', 'Cuando yo ', ' pequeño, soñaba con viajar por todo el mundo.', 'ser', '[{"form":"era","type":"imperfect","correct":true},{"form":"fui","type":"preterite","correct":false}]'::jsonb, '"Cuando era pequeño" (when I was little) describes a stage of life, which is background. Use the imperfect: era. Careful: fui is the preterite of both ser and ir.', 'When I was little, I dreamed of travelling all over the world.', 'anim_globe_spin_loop')
