insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000302', 'dormitorio', 2, 'window_clouds_01', 'Cuando llegué a casa, el cielo ', ' muy nublado.', 'estar', '[{"form":"estaba","type":"imperfect","correct":true},{"form":"estuvo","type":"preterite","correct":false}]'::jsonb, '"Llegué" is the event; the sky is the scene it happened in. States and descriptions take the imperfect: estaba. Estuvo (stem estuv-) would mean a closed period.', 'When I got home, the sky was very cloudy.', 'anim_clouds_drift_loop')
