insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000303', 'dormitorio', 3, 'phone_01', 'Ya me ', ' a la cama cuando, de repente, sonó el teléfono.', 'ir', '[{"form":"iba","type":"imperfect","correct":true},{"form":"fui","type":"preterite","correct":false}]'::jsonb, 'An action already in progress that gets interrupted ("sonó") takes the imperfect. Ir is one of only three irregular imperfects: iba, ibas, iba (the others are ser and ver).', 'I was already going to bed when, suddenly, the phone rang.', 'anim_phone_ring_loop')
