insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000304', 'dormitorio', 4, 'bookshelf_01', 'Mientras yo dormía, un libro se ', ' de la estantería.', 'caer', '[{"form":"caía","type":"imperfect","correct":false},{"form":"cayó","type":"preterite","correct":true}]'::jsonb, '"Dormía" is the background; the book falling is the single event that interrupts it. Use the preterite. Caer changes i to y: cayó, cayeron.', 'While I was sleeping, a book fell off the shelf.', 'anim_book_fall_once')
