insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000305', 'dormitorio', 5, 'vase_01', 'Esa mañana ', ' al mercado y compré flores frescas.', 'ir', '[{"form":"iba","type":"imperfect","correct":false},{"form":"fui","type":"preterite","correct":true}]'::jsonb, '"Esa mañana" (that morning) points to one specific occasion, followed by another completed action ("compré"). Use the preterite: fui. It is the same form as ser''s preterite, so context tells you which verb it is.', 'That morning I went to the market and bought fresh flowers.', 'anim_flowers_bloom_once')
