insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000405', 'cafeteria', 5, 'oven_01', 'De repente, mi amiga ', ' un olor a pan recién hecho.', 'sentir', '[{"form":"sentía","type":"imperfect","correct":false},{"form":"sintió","type":"preterite","correct":true}]'::jsonb, '"De repente" marks a sudden, one-time perception: sintió. Sentir changes e→i in the third person preterite (sintió, sintieron) but is regular in the imperfect (sentía).', 'Suddenly, my friend noticed the smell of freshly baked bread.', 'anim_oven_bread_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000501', 'estacion', 1, 'clock_station_01', 'El reloj de la estación siempre ', ' cinco minutos adelantado.', 'ir', '[{"form":"iba","type":"imperfect","correct":true},{"form":"fue","type":"preterite","correct":false}]'::jsonb, 'This describes how the clock usually was, not an event: iba. ("Ir adelantado" means a clock is fast.) Ir is irregular in the imperfect: iba, ibas, iba.', 'The station clock was always five minutes fast.', 'anim_pendulum_swing_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000502', 'estacion', 2, 'speaker_01', 'Cada cinco minutos, una voz ', ' lo mismo por el altavoz.', 'decir', '[{"form":"decía","type":"imperfect","correct":true},{"form":"dijo","type":"preterite","correct":false}]'::jsonb, '"Cada cinco minutos" is a repeated action, so use the imperfect: decía. Decir is regular in the imperfect, but its preterite has a -j- stem: dije, dijo, dijeron.', 'Every five minutes, a voice said the same thing over the loudspeaker.', 'anim_speaker_announce_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000503', 'estacion', 3, 'pigeon_01', 'Mientras esperábamos, una paloma ', ' de un lado a otro del andén.', 'andar', '[{"form":"andaba","type":"imperfect","correct":true},{"form":"anduvo","type":"preterite","correct":false}]'::jsonb, 'Two things going on at the same time in the background ("mientras esperábamos") both take the imperfect: andaba. Andar''s preterite is irregular, with a -uv- stem: anduve, anduvo.', 'While we were waiting, a pigeon was walking up and down the platform.', 'anim_pigeon_walk_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000504', 'estacion', 4, 'train_01', 'Por fin, a las ocho en punto, el tren ', ' a la estación.', 'llegar', '[{"form":"llegaba","type":"imperfect","correct":false},{"form":"llegó","type":"preterite","correct":true}]'::jsonb, '"Por fin" and an exact time ("a las ocho en punto") mark one completed event: llegó.', 'Finally, at exactly eight o''clock, the train arrived at the station.', 'anim_train_arrive_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000505', 'estacion', 5, 'suitcase_01', 'Mi tía bajó del tren y me ', ' una maleta llena de regalos.', 'traer', '[{"form":"traía","type":"imperfect","correct":false},{"form":"trajo","type":"preterite","correct":true}]'::jsonb, 'This is a chain of events (bajó, then the next action), so use the preterite: trajo. Traer has a -j- stem in the preterite: traje, trajo, trajeron (not "trajieron").', 'My aunt got off the train and brought me a suitcase full of presents.', 'anim_suitcase_open_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000601', 'aula', 1, 'globe_01', 'De niña, ', ' todas las capitales de Europa de memoria.', 'saber', '[{"form":"sabía","type":"imperfect","correct":true},{"form":"supe","type":"preterite","correct":false}]'::jsonb, 'Knowing something over time is a state, so use the imperfect: sabía (I knew). In the preterite, supe means "I found out", which is a different meaning.', 'As a girl, I knew all the capitals of Europe by heart.', 'anim_globe_spin_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000602', 'aula', 2, 'chalkboard_01', 'Ese día ', ' la verdad: la profesora se jubilaba.', 'saber', '[{"form":"sabía","type":"imperfect","correct":false},{"form":"supe","type":"preterite","correct":true}]'::jsonb, 'Here saber means "to find out", a moment of discovery. That meaning only exists in the preterite: supe. Sabía would mean "I already knew".', 'That day I found out the truth: the teacher was retiring.', 'anim_chalk_write_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000603', 'aula', 3, 'door_01', 'En septiembre ', ' a Lucía, la chica nueva de la clase.', 'conocer', '[{"form":"conocía","type":"imperfect","correct":false},{"form":"conocí","type":"preterite","correct":true}]'::jsonb, 'Meeting someone for the first time is an event: conocí (I met). Conocía would mean "I already knew her".', 'In September I met Lucía, the new girl in class.', 'anim_door_open_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000604', 'aula', 4, 'clock_wall_01', 'Siempre ', ' salir al recreo antes de tiempo, pero la profesora no nos dejaba.', 'querer', '[{"form":"queríamos","type":"imperfect","correct":true},{"form":"quisimos","type":"preterite","correct":false}]'::jsonb, 'An ongoing wish is a state: queríamos (we wanted). In the preterite, quisimos suggests we actually tried, and "no quisimos" means "we refused".', 'We always wanted to go out for break early, but the teacher wouldn''t let us.', 'anim_pendulum_swing_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000605', 'aula', 5, 'trophy_01', 'Después de mucho estudiar, por fin ', ' aprobar el examen de matemáticas.', 'poder', '[{"form":"podía","type":"imperfect","correct":false},{"form":"pude","type":"preterite","correct":true}]'::jsonb, '"Por fin" marks a result. In the preterite, poder means "managed to": pude aprobar. Podía only means "I was able to", with no sign that it actually happened.', 'After a lot of studying, I finally managed to pass the maths exam.', 'anim_trophy_rise_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000701', 'taller', 1, 'radio_vintage_01', 'Mientras trabajaba, el abuelo siempre ', ' la radio.', 'poner', '[{"form":"ponía","type":"imperfect","correct":true},{"form":"puso","type":"preterite","correct":false}]'::jsonb, '"Siempre" plus "mientras trabajaba" describes a habit, so use the imperfect: ponía. Poner is regular in the imperfect but irregular in the preterite (puse, puso).', 'While he worked, Grandpa always put the radio on.', 'anim_radio_music_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000702', 'taller', 2, 'lamp_workshop_01', 'La vieja lámpara ', ' una luz amarilla sobre la mesa de trabajo.', 'dar', '[{"form":"daba","type":"imperfect","correct":true},{"form":"dio","type":"preterite","correct":false}]'::jsonb, 'Describing what a place was like is background, so use the imperfect: daba. Dar''s preterite is irregular and has no accent: di, dio.', 'The old lamp gave off a yellow light over the workbench.', 'anim_lamp_glow_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000703', 'taller', 3, 'window_sea_01', 'Desde la ventana del taller ', ' el mar.', 'ver', '[{"form":"veíamos","type":"imperfect","correct":true},{"form":"vimos","type":"preterite","correct":false}]'::jsonb, 'What you could see from a place is a description: veíamos. Ver is one of only three irregular imperfects (it keeps the e: veía), along with ser and ir.', 'From the workshop window we could see the sea.', 'anim_sea_waves_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000704', 'taller', 4, 'toy_boat_01', 'En una sola tarde, el abuelo ', ' un barco de madera para mí.', 'hacer', '[{"form":"hacía","type":"imperfect","correct":false},{"form":"hizo","type":"preterite","correct":true}]'::jsonb, '"En una sola tarde" (in a single afternoon) presents the job as finished, so use the preterite: hizo. Watch the spelling: hice, but hizo (c→z).', 'In a single afternoon, Grandpa made me a wooden boat.', 'anim_boat_build_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000705', 'taller', 5, 'toolbox_01', 'Al final del verano, el abuelo me ', ' su vieja caja de herramientas.', 'dar', '[{"form":"daba","type":"imperfect","correct":false},{"form":"dio","type":"preterite","correct":true}]'::jsonb, '"Al final del verano" points to one moment when something happened: dio. In the preterite, dar takes -er/-ir endings and no accent: di, diste, dio.', 'At the end of the summer, Grandpa gave me his old toolbox.', 'anim_toolbox_open_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000801', 'tormenta', 1, 'window_storm_01', 'Era de noche, ', ' muchísimo y hacía viento.', 'llover', '[{"form":"llovía","type":"imperfect","correct":true},{"form":"llovió","type":"preterite","correct":false}]'::jsonb, '"Era de noche" and "hacía viento" set the scene. The rain is part of that scene: llovía.', 'It was night, it was pouring and it was windy.', 'anim_storm_rain_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000802', 'tormenta', 2, 'rocking_chair_01', 'Mi abuela ', ' tranquila en su mecedora.', 'estar', '[{"form":"estaba","type":"imperfect","correct":true},{"form":"estuvo","type":"preterite","correct":false}]'::jsonb, 'Describing where someone was and how they felt is background: estaba. Estuvo would present it as a closed, finished period.', 'My grandmother was sitting calmly in her rocking chair.', 'anim_chair_rock_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000803', 'tormenta', 3, 'candle_01', 'De repente, se ', ' la luz y encendimos una vela.', 'irse', '[{"form":"iba","type":"imperfect","correct":false},{"form":"fue","type":"preterite","correct":true}]'::jsonb, '"De repente" marks the event that breaks into the scene. "Irse la luz" means the power going out: se fue. It''s the preterite of ir, which has the same form as ser''s.', 'Suddenly, the power went out and we lit a candle.', 'anim_candle_light_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000804', 'tormenta', 4, 'door_01', 'A medianoche, ', ' un ruido y la puerta se abrió sola.', 'oír', '[{"form":"oíamos","type":"imperfect","correct":false},{"form":"oímos","type":"preterite","correct":true}]'::jsonb, '"A medianoche" pins the event to one moment, so use the preterite: oímos. In the third person, oír changes i to y: oyó, oyeron.', 'At midnight we heard a noise and the door opened by itself.', 'anim_door_open_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000805', 'tormenta', 5, 'clock_wall_01', 'Mientras esperábamos a que volviera la luz, el viejo reloj ', ' las horas.', 'dar', '[{"form":"daba","type":"imperfect","correct":true},{"form":"dio","type":"preterite","correct":false}]'::jsonb, '"Mientras esperábamos" is background, and the clock striking hour after hour is too: daba.', 'While we waited for the power to come back, the old clock struck the hours.', 'anim_pendulum_swing_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000901', 'fiesta', 1, 'balloons_01', 'En el salón ', ' globos de todos los colores.', 'haber', '[{"form":"había","type":"imperfect","correct":true},{"form":"hubo","type":"preterite","correct":false}]'::jsonb, 'To describe what was in a place, use había (there was / there were). In this meaning, haber stays singular even before plural nouns.', 'In the living room there were balloons of every colour.', 'anim_balloons_float_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000902', 'fiesta', 2, 'radio_vintage_01', 'Mientras comíamos, ', ' música de los años setenta.', 'sonar', '[{"form":"sonaba","type":"imperfect","correct":true},{"form":"sonó","type":"preterite","correct":false}]'::jsonb, 'Background music during another activity ("mientras comíamos") takes the imperfect: sonaba.', 'While we were eating, seventies music was playing.', 'anim_radio_music_loop')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000903', 'fiesta', 3, 'door_01', 'A las seis ', ' mis primos con un regalo enorme.', 'venir', '[{"form":"venían","type":"imperfect","correct":false},{"form":"vinieron","type":"preterite","correct":true}]'::jsonb, 'An exact time ("a las seis") marks an arrival, which is an event: vinieron. Venir''s preterite stem is vin-: vine, vino, vinieron.', 'At six o''clock my cousins came with an enormous present.', 'anim_door_open_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000904', 'fiesta', 4, 'cake_01', 'Luego mi madre ', ' la tarta en la mesa y todos cantamos.', 'poner', '[{"form":"ponía","type":"imperfect","correct":false},{"form":"puso","type":"preterite","correct":true}]'::jsonb, '"Luego" (then) moves the story forward: puso. Poner has an irregular stem, pus-, and no accents: puse, puso.', 'Then my mother put the cake on the table and we all sang.', 'anim_cake_arrive_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000000905', 'fiesta', 5, 'window_fireworks_01', 'A medianoche ', ' fuegos artificiales y todos salimos al jardín.', 'haber', '[{"form":"había","type":"imperfect","correct":false},{"form":"hubo","type":"preterite","correct":true}]'::jsonb, 'Here haber means that something happened (an event), not that something was there. For events, use the preterite: hubo.', 'At midnight there were fireworks and we all went out into the garden.', 'anim_fireworks_burst_once')
  on conflict (id) do update set room_id = excluded.room_id, order_index = excluded.order_index, scene_object = excluded.scene_object, sentence_pre = excluded.sentence_pre, sentence_post = excluded.sentence_post, verb_base = excluded.verb_base, options = excluded.options, rule_feedback = excluded.rule_feedback, translation = excluded.translation, anim_trigger = excluded.anim_trigger;
insert into todo.tense_puzzles (id, room_id, order_index, scene_object, sentence_pre, sentence_post, verb_base, options, rule_feedback, translation, anim_trigger) values ('00000000-0000-4000-8000-000000001001', 'despedida', 1, 'boxes_01', 'Mis padres ', ' en esta casa durante treinta años.', 'vivir', '[{"form":"vivían","type":"imperfect","correct":false},{"form":"vivieron","type":"preterite","correct":true}]'::jsonb, 'Even a long time counts as one closed block when its length is given and it''s over ("durante treinta años"), so use the preterite: vivieron.', 'My parents lived in this house for thirty years.', 'anim_boxes_stack_once')
